window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["system-prompt"]={"title":"系统提示：在概率模型里声明行为契约，而不是建立安全边界","subtitle":"从消息序列、指令优先级、冲突解析和上下文拼装，到注入、泄露、版本化与契约测试，理解系统提示能控制什么。","thesis":"系统提示是应用在每次推理中注入的高优先级上下文，用来声明角色、任务、边界和输出契约；它影响下一 token 分布，却不是操作系统权限，不能独立保护秘密或阻止越权工具。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"用户要求退800元","rule":"超过500元需批准","steps":"退款工具根据登录主体","interpretation":"提示通过不代表退款获准"}},{"section":4,"evidence":{"setup":"建立200条契约测试","rule":"一次只改变规则表达","steps":"长版通过170条","interpretation":"净收益为负表示回归多于修复"}}],"formulas":[{"id":"system-prompt-contract-metrics","section":4,"formulaIndex":1,"symbols":[{"name":"r","meaning":"契约测试通过率","evidence":"r 是契约测试通过率"},{"name":"m","meaning":"通过的测试条数","evidence":"m 是通过的测试条数"},{"name":"n","meaning":"测试总条数","evidence":"n 是测试总条数"},{"name":"Δ","meaning":"版本相对基线的净收益","evidence":"Δ 是版本相对基线的净收益"},{"name":"f","meaning":"新版本修复的旧失败数","evidence":"f 是新版本修复的旧失败数"},{"name":"g","meaning":"新版本造成的新回归数","evidence":"g 是新版本造成的新回归数"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"系统提示是应用在每次推理中注入的高优先级行为契约 token。","evidence":"系统提示的输入是应用注入的角色、任务、行为边界和输出契约"},"problem":{"answer":"它为同一模型声明当前应用角色、任务边界和输出要求。","evidence":"文本是否变成模型不可违反的程序"},"inputOutput":{"answer":"输入角色、任务和契约，输出这些 token 条件下的回答分布。","evidence":"输出是这些 token 条件下的回答分布"},"mechanism":{"answer":"聊天模板编码角色，训练提高模型遵循高优先级指令的倾向。","evidence":"训练提高遵循高优先级指令的倾向"},"interpretation":{"answer":"遵循只表示概率行为符合预期，不是形式规则被执行。","evidence":"遵循结果只能当概率行为"},"boundary":{"answer":"秘密、身份、权限和副作用必须由模型外系统保护。","evidence":"必须由模型外系统控制"}},{"section":2,"definition":{"answer":"指令优先级按消息信任角色解决跨层冲突，而非只看出现时间。","evidence":"优先级解决冲突，时间顺序只补充同层上下文"},"problem":{"answer":"它解决用户、系统和不可信数据给出相反指令时应听谁的问题。","evidence":"用户消息为什么不应覆盖更早的系统约束"},"inputOutput":{"answer":"输入带角色来源和时间的消息，输出应执行任务和被忽略冲突。","evidence":"输出应执行的高层任务和被忽略的低层冲突"},"mechanism":{"answer":"系统开发者高于用户，网页工具文本只作数据，同层才按新意图更新。","evidence":"同一层才用较新意图补充"},"interpretation":{"answer":"优先级表示设计期望，运行时仍要检查模型是否实际遵守。","evidence":"优先级是期望规则，不是执行保证"},"boundary":{"answer":"模型可能解析冲突失败，因此副作用仍需确定性验证。","evidence":"运行时仍须验证输出与副作用"}},{"section":3,"definition":{"answer":"退款案例把系统提示、结构化提议、策略门和业务工具分层。","evidence":"退款助手的契约怎样从需求变成提示与硬门"},"problem":{"answer":"它说明超过五百元需批准不能只写成自然语言提示。","evidence":"超过500元需批准"},"inputOutput":{"answer":"输入请求、订单、金额规则与主体，输出退款提议或缺信息状态。","evidence":"输出是结构化退款提议或缺信息状态"},"mechanism":{"answer":"模型提出意图，策略门核验所有权金额令牌，工具执行并返回状态。","evidence":"确定性策略门再核验所有权、金额与审批令牌"},"interpretation":{"answer":"模型说可退款只表示建议，不表示现实退款已经获准。","evidence":"提示通过不代表退款获准"},"boundary":{"answer":"超过五百元且没有批准令牌时，执行器必须拒绝。","evidence":"执行器必须拒绝"}},{"section":4,"definition":{"answer":"提示消融是在同一契约测试集上只改变一个提示因素的实验。","evidence":"系统提示预算要用消融实验而不是越写越长"},"problem":{"answer":"它区分新增规则效果下降来自表达冲突还是上下文竞争。","evidence":"规则冲突还是上下文竞争"},"inputOutput":{"answer":"输入多个提示版本和固定测试集，输出通过、修复、回归、成本与延迟。","evidence":"输出通过率、修复数、回归数、成本和延迟"},"mechanism":{"answer":"一次只改规则表达并逐切片比较新修复与新回归。","evidence":"一次只改变规则表达并逐切片比较"},"interpretation":{"answer":"净收益为负表示新增回归超过修复，不应发布。","evidence":"净收益为负表示回归多于修复"},"boundary":{"answer":"总通过率可能掩盖关键安全回归，不能独自决定发布。","evidence":"不能独自决定发布"}},{"section":5,"definition":{"answer":"权限分层让模型只提意图，策略门授权，业务工具改变真实状态。","evidence":"提示契约与执行权限必须分层"},"problem":{"answer":"它保证模型遭到注入时仍有模型外层阻止真实副作用。","evidence":"哪一层仍能阻止真实副作用"},"inputOutput":{"answer":"输入结构化意图和权威状态，输出允许、拒绝或待审批工具调用。","evidence":"输出允许、拒绝或待审批的工具调用"},"mechanism":{"answer":"策略门核验身份金额目标域，工具负责幂等执行并回传事实。","evidence":"确定性策略门执行校验"},"interpretation":{"answer":"图中箭头表示控制流，不表示提示拥有现实授权。","evidence":"箭头表示控制流"},"boundary":{"answer":"系统提示不能替代身份、业务规则和工具权限校验。","evidence":"不表示系统提示本身拥有授权能力"}},{"section":6,"definition":{"answer":"最小分区提示将稳定目标、信任边界、流程、schema 和失败处理分开。","evidence":"最小、分区、无矛盾的契约"},"problem":{"answer":"它减少角色、政策、数据和示例混写造成的冲突与维护困难。","evidence":"混在一段里会发生什么"},"inputOutput":{"answer":"输入规则动态数据和边界，输出最小、分区且无矛盾的契约。","evidence":"输出最小、分区且无矛盾的行为契约"},"mechanism":{"answer":"稳定规则留提示，动态数据结构化注入，冲突明示优先级和回退。","evidence":"频繁变化的数据通过结构化配置或检索注入"},"interpretation":{"answer":"分区后更易定位规则来源和测试失败，不表示越短必然越好。","evidence":"提示越短并不自动越好"},"boundary":{"answer":"任何删减都必须用覆盖边界的正反例重新验收。","evidence":"仍须用覆盖边界的正反例验收"}},{"section":7,"definition":{"answer":"提示注入利用不可信数据与指令共享同一 token 和注意力通道。","evidence":"提示注入利用的是指令与数据共享通道"},"problem":{"answer":"它解释 XML 标签为何只能提示边界而不能提供真实隔离。","evidence":"为什么只能降低混淆而不能隔离"},"inputOutput":{"answer":"输入可信指令和恶意外部数据，输出模型意图及实际工具动作。","evidence":"输出模型意图和实际工具动作"},"mechanism":{"answer":"恶意 token 仍参与注意力，可能诱导模型改写目标或调用工具。","evidence":"恶意 token 仍参加同一注意力计算"},"interpretation":{"answer":"标签降低混淆不等于建立权限边界或证明抵抗攻击。","evidence":"标签只能提示“这是数据”"},"boundary":{"answer":"防线必须包括最小上下文、白名单、最小权限和审批。","evidence":"真正防线是最小上下文、工具白名单、最小权限与审批"}},{"section":8,"definition":{"answer":"系统提示不是秘密存储，应默认其文本或语义可能被复述和推断。","evidence":"系统提示不是秘密存储"},"problem":{"answer":"它解决哪些政策可以公开写入、哪些敏感资产必须留在服务端的问题。","evidence":"是否可以放内部政策和检测阈值"},"inputOutput":{"answer":"输入提示资产和攻击路径，输出复述、推断与实际损失判断。","evidence":"输出原文复述、语义推断与实际安全损失"},"mechanism":{"answer":"攻击可通过直接索要、逐段推断、错误回显或工具日志获取内容。","evidence":"直接索要、角色扮演、逐段推断、错误回显或工具日志"},"interpretation":{"answer":"公开规范被复述未必是事故，必须按资产价值判断。","evidence":"公开行为规范被复述未必是事故"},"boundary":{"answer":"密钥、个人数据和敏感检测逻辑绝不能进入提示上下文。","evidence":"不能进入上下文"}},{"section":9,"definition":{"answer":"输出契约用版本化 schema 和明确状态表达建议、拒绝与缺信息。","evidence":"输出结构与拒绝路径必须可被消费者验证"},"problem":{"answer":"它避免下游仅凭模型一句自然语言就触发现实副作用。","evidence":"下游为何不能只读这句话"},"inputOutput":{"answer":"输入模型建议，输出版本化状态字段和拒绝原因。","evidence":"输出版本化状态、字段和拒绝原因"},"mechanism":{"answer":"消费者依次校验类型、枚举、跨字段、身份和业务状态。","evidence":"依次做类型、枚举、跨字段、身份和业务状态校验"},"interpretation":{"answer":"结构合法只说明格式通过，不说明业务语义正确。","evidence":"结构合法只表示格式通过"},"boundary":{"answer":"自由文本解释不能触发副作用，权限仍以权威系统为准。","evidence":"自由文本解释不触发副作用"}},{"section":10,"definition":{"answer":"长时状态装配将系统规则、历史、摘要、工具观察和记忆组成每轮上下文。","evidence":"会话、摘要和记忆会让旧提示假设漂移"},"problem":{"answer":"它解释系统提示未改时长对话行为仍会变化的原因。","evidence":"为什么长对话后行为仍可能变化"},"inputOutput":{"answer":"输入不变量、历史摘要与记忆，输出本轮模型可见上下文。","evidence":"输出本轮模型可见上下文"},"mechanism":{"answer":"每轮重申边界、携带来源状态，任务切换时清除局部记忆。","evidence":"任务切换时清除局部记忆"},"interpretation":{"answer":"行为漂移可能来自条件上下文变化，不一定是系统提示文件变化。","evidence":"历史消息、压缩摘要、工具观察和记忆不断改变条件上下文"},"boundary":{"answer":"初始规则出现一次不能保证压缩后仍保留或阻止旧目标残留。","evidence":"不能保证摘要后仍存在"}},{"section":11,"definition":{"answer":"提示版本发布把提示及关联模型、模板、schema 和评测证据一起管理。","evidence":"版本化提示像代码"},"problem":{"answer":"它发现一句措辞修改对其他语言、任务、工具和拒绝行为的旁路影响。","evidence":"为什么也可能改变完全无关的任务"},"inputOutput":{"answer":"输入全套版本和回归集，输出带证据的候选版本与回滚包。","evidence":"输出带回归证据的候选版本与回滚包"},"mechanism":{"answer":"灰度比较任务成功、冲突、误拒、成本和人工修正。","evidence":"灰度比较任务成功、冲突、误拒、成本和人工修正"},"interpretation":{"answer":"文本 diff 只说明改动内容，不能证明行为没有回归。","evidence":"文本 diff 只说明改了什么"},"boundary":{"answer":"异常时必须能同时回滚提示和关联 schema。","evidence":"同时回滚提示与关联schema"}},{"section":12,"definition":{"answer":"契约测试用正常、冲突、恶意和故障四类样本验证行为边界。","evidence":"契约测试覆盖正常、冲突、恶意和故障四象限"},"problem":{"answer":"它避免只测理想对话而漏掉冲突、攻击和工具故障。","evidence":"不能只保存几个理想对话"},"inputOutput":{"answer":"输入四类样本，输出结构、决策、副作用与事实断言结果。","evidence":"输出结构、决策、副作用与用户可见事实的断言结果"},"mechanism":{"answer":"按语言长度版本风险切片执行，并保存失败与置信区间。","evidence":"按语言、长度、版本和风险切片统计"},"interpretation":{"answer":"措辞可变化，但高风险动作和事实边界必须确定性通过。","evidence":"高风险动作和事实边界必须确定性通过"},"boundary":{"answer":"模型评审只能辅助扩展，高风险判定仍需确定性检查或人工。","evidence":"高风险判定使用确定性检查或人工复核"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>解释系统消息怎样参与自回归生成；区分优先级、时间顺序与可信度；把提示拆成可测试的行为契约；设计冲突和注入回归集；将硬安全约束下沉到确定性执行层。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>系统提示仍然只是模型看到的一串 token<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">标为 system 后，文本是否变成模型不可违反的程序？</p><p>系统提示的输入是应用注入的角色、任务、行为边界和输出契约，输出是这些 token 条件下的回答分布。聊天模板把消息角色编码进前缀，训练提高遵循高优先级指令的倾向，但没有形式解释器逐条强制执行。遵循结果只能当概率行为；秘密、身份和现实权限必须由模型外系统控制。</p><p>聊天运行时把不同角色的消息按模板编码，模型仍对整个前缀计算条件概率。训练让模型更倾向遵守高优先级角色，但生成过程没有一个逐条执行规则的形式化解释器；提示越长、冲突越隐蔽、任务越陌生，遵循可能越不稳定。</p><p>因此系统提示适合声明行为预期和协调上下文，不适合保存 API 密钥、实施租户隔离或授权付款。真正不可越过的边界必须由工具参数校验、身份权限和业务策略提供。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>优先级解决冲突，时间顺序只补充同层上下文<span class=\"dd-badge eng\">机制</span></h2><p class=\"dd-lead\">后出现的用户消息为什么不应覆盖更早的系统约束？</p><p>冲突解析接收带角色、来源与时间的消息序列，输出应执行的高层任务和被忽略的低层冲突。系统或开发者约束高于用户目标，不可信网页与工具文本只作为数据；同一层才用较新意图补充。优先级是期望规则，不是执行保证，所以运行时仍须验证输出与副作用。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>来源</th><th>信任角色</th><th>应当怎样处理</th></tr></thead><tbody><tr><td>系统/开发者</td><td>应用策略与任务契约</td><td>约束低层指令</td></tr><tr><td>用户</td><td>目标和输入</td><td>在高层允许范围内执行</td></tr><tr><td>检索/网页/工具输出</td><td>不可信数据</td><td>作为事实候选，不自动当命令</td></tr><tr><td>历史摘要/记忆</td><td>派生状态</td><td>带来源、作用域和可纠正性</td></tr></tbody></table></div><p>同层消息可按较新意图更新，但跨层冲突应由信任优先级决定。模型可能执行失败，因此运行时仍要验证结果。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>完整示例：退款助手的契约怎样从需求变成提示与硬门<span class=\"dd-badge eng\">案例推演</span></h2><p class=\"dd-lead\">“退款超过500元需批准”应该只写进系统提示吗？</p><p>案例输入是退款请求、订单事实、金额规则和登录主体，输出是结构化退款提议或缺信息状态，而不是直接改账。模型负责解释并提出意图，确定性策略门再核验所有权、金额与审批令牌，工具返回真实状态。提示通过不代表退款获准；超过五百元且无批准时执行器必须拒绝。</p><ol class=\"dd-steps\"><li>系统提示声明职责：解释政策、收集订单信息、提出退款建议，不声称已经执行。</li><li>把订单数据放入带来源的结构化区块，并明确其中自由文本不可信。</li><li>要求输出建议、证据订单ID、金额和是否需人工批准的schema。</li><li>用户要求退800元时，模型可解释并生成待审批提议。</li><li>退款工具根据登录主体、订单所有权、金额和审批令牌独立拒绝未批准调用。</li><li>返回工具状态后，模型只能报告真实结果，不能把“已提交”写成“已到账”。</li><li>测试正常、边界金额、缺字段、用户覆盖规则、订单备注注入和工具报错。</li></ol><p>提示改善决策和解释；执行器拥有最终权威。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>系统提示预算要用消融实验而不是越写越长<span class=\"dd-badge math\">数值例子</span></h2><p class=\"dd-lead\">新增一页规则后效果下降，怎样判断是规则冲突还是上下文竞争？</p><p>提示消融输入短版、长版和结构化改写版以及同一契约测试集，输出通过率、修复数、回归数、成本和延迟。一次只改变规则表达并逐切片比较；净收益为负表示回归多于修复。单一总通过率仍可能掩盖关键安全回归，因此不能独自决定发布。</p><p>建立200条契约测试。短版提示通过176条，遵循率88%；长版通过170条，85%，其中旧能力回归12条、新规则修复6条，净变化−6。再将新增规则拆成结构化冲突表，若通过184条即92%，说明问题来自表达和冲突，而非“模型记不住所有规则”的单一解释。</p><div class=\"dd-formula\" data-formula-id=\"system-prompt-contract-metrics\"><math display=\"block\" aria-label=\"通过率 r 等于通过数 m 除以测试总数 n；净收益 delta 等于新修复数 f 减去新回归数 g，本例为六减十二等于负六\"><mtable><mtr><mtd><mi>r</mi><mo>=</mo><mfrac><mi>m</mi><mi>n</mi></mfrac></mtd></mtr><mtr><mtd><mi>Δ</mi><mo>=</mo><mi>f</mi><mo>−</mo><mi>g</mi><mo>=</mo><mn>6</mn><mo>−</mo><mn>12</mn><mo>=</mo><mo>−</mo><mn>6</mn></mtd></mtr></mtable></math></div><p class=\"dd-formula-note\"><code>r</code> 是契约测试通过率，<code>m</code> 是通过的测试条数，<code>n</code> 是测试总条数；<code>Δ</code> 是版本相对基线的净收益，<code>f</code> 是新版本修复的旧失败数，<code>g</code> 是新版本造成的新回归数。负 Δ 表示新增回归多于修复，不能因局部新规则生效就发布。</p><p>还要测token成本、首字延迟和不同任务切片，不以单个示例决定版本。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：提示契约与执行权限必须分层<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">模型被注入时，哪一层仍能阻止真实副作用？</p><p>分层系统输入模型提出的结构化意图及身份、金额、目标域等权威状态，输出允许、拒绝或待审批的工具调用。概率模型只提出意图，确定性策略门执行校验，业务工具负责幂等状态变化并回传事实。图中的箭头表示控制流，不表示系统提示本身拥有授权能力。</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 760 335\" role=\"img\" aria-label=\"系统提示与用户目标、不可信数据进入模型，模型提出结构化意图，再经策略权限和业务工具验证\"><defs><marker id=\"sp31\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0L6,3L0,6z\" fill=\"#7f8b9d\"/></marker></defs><rect x=\"24\" y=\"42\" width=\"128\" height=\"62\" rx=\"9\" fill=\"#21252d\" stroke=\"#72b293\"/><text x=\"88\" y=\"70\" text-anchor=\"middle\" class=\"svg-t\">系统契约</text><text x=\"88\" y=\"91\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">目标/边界/schema</text><rect x=\"24\" y=\"126\" width=\"128\" height=\"62\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"88\" y=\"162\" text-anchor=\"middle\" class=\"svg-t\">用户目标</text><rect x=\"24\" y=\"210\" width=\"128\" height=\"62\" rx=\"9\" fill=\"#21252d\" stroke=\"#cf7c72\"/><text x=\"88\" y=\"238\" text-anchor=\"middle\" class=\"svg-t\">不可信数据</text><text x=\"88\" y=\"259\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">网页/工具/文档</text><path d=\"M152 73L207 137M152 157H207M152 241L207 177\" stroke=\"#7f8b9d\" marker-end=\"url(#sp31)\"/><rect x=\"212\" y=\"96\" width=\"132\" height=\"122\" rx=\"9\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"278\" y=\"126\" text-anchor=\"middle\" class=\"svg-t\">概率模型</text><text x=\"278\" y=\"153\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">冲突解析不保证</text><text x=\"278\" y=\"180\" text-anchor=\"middle\" class=\"svg-t\">提出意图</text><path d=\"M344 157H389\" stroke=\"#7f8b9d\" marker-end=\"url(#sp31)\"/><rect x=\"394\" y=\"96\" width=\"138\" height=\"122\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"463\" y=\"126\" text-anchor=\"middle\" class=\"svg-t\">确定性策略门</text><text x=\"463\" y=\"153\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">身份/金额/目标域</text><text x=\"463\" y=\"180\" text-anchor=\"middle\" class=\"svg-t\">允许/拒绝/审批</text><path d=\"M532 157H577\" stroke=\"#7f8b9d\" marker-end=\"url(#sp31)\"/><rect x=\"582\" y=\"96\" width=\"150\" height=\"122\" rx=\"9\" fill=\"#21252d\" stroke=\"#72b293\"/><text x=\"657\" y=\"126\" text-anchor=\"middle\" class=\"svg-t\">业务工具</text><text x=\"657\" y=\"153\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">真实状态/幂等</text><text x=\"657\" y=\"180\" text-anchor=\"middle\" class=\"svg-t\">审计结果</text><path d=\"M657 218V286H278V218\" fill=\"none\" stroke=\"#cf7c72\" stroke-dasharray=\"6 5\" marker-end=\"url(#sp31)\"/><text x=\"468\" y=\"311\" text-anchor=\"middle\" class=\"svg-t\">工具事实返回模型；提示不能伪造执行成功</text></svg><figcaption>图 1　系统提示管理模型行为，确定性策略管理现实权限。</figcaption></figure></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>把提示写成最小、分区、无矛盾的契约<span class=\"dd-badge eng\">设计</span></h2><p class=\"dd-lead\">角色口吻、政策、数据和例子混在一段里会发生什么？</p><p>提示设计输入稳定目标、动态数据、信任边界、失败处理和输出 schema，输出最小、分区且无矛盾的行为契约。稳定规则留在提示，频繁变化的数据通过结构化配置或检索注入；冲突时明示优先关系与保守回退。提示越短并不自动越好，删减后仍须用覆盖边界的正反例验收。</p><p>按稳定目标、不可违反约束、输入信任边界、决策流程、输出schema和失败处理分区；用同一术语表达主体和动作，写清适用与不适用。把会频繁变化的业务数据放到结构化配置或检索，不复制进长提示。</p><p>规则冲突时明示优先关系和保守回退，例如“资料不足时询问，不猜测；涉及写操作先提议再批准”。少量覆盖边界的正反例比大量风格示例更有价值。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>提示注入利用的是指令与数据共享通道<span class=\"dd-badge eng\">失败边界</span></h2><p class=\"dd-lead\">用XML标签包住网页内容，为什么只能降低混淆而不能隔离？</p><p>注入测试输入可信指令与含恶意文本的网页、文档或工具结果，输出模型意图和实际工具动作。标签只能提示“这是数据”，恶意 token 仍参加同一注意力计算；真正防线是最小上下文、工具白名单、最小权限与审批。只通过一种“忽略之前指令”模板不能证明抵抗多语言、编码或多轮攻击。</p><p>标签、引号和“不要执行以下内容”给模型提供语义提示，但网页里的恶意文本仍进入同一上下文并参与注意力。间接注入可要求泄露提示、改写目标或调用工具；模型可能在长链条里忘记信任边界。</p><p>把外部内容视为数据，最小化可见上下文；工具使用最小权限和目标白名单；敏感动作由确定性策略或人批准。用多语言、编码、长上下文和工具返回中的注入测试，而非只测“忽略之前指令”。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>系统提示不是秘密存储，防泄露要假设它可被推断<span class=\"dd-badge eng\">保密</span></h2><p class=\"dd-lead\">提示里不直接展示密钥，是否可以放内部政策和检测阈值？</p><p>泄露评测输入系统提示资产、攻击提问和日志工具路径，输出原文复述、语义推断与实际安全损失。默认假设提示可被复述或推断，因此密钥、个人数据和敏感检测逻辑不能进入上下文。公开行为规范被复述未必是事故，是否失败必须先按资产价值定义。</p><p>用户可通过直接索要、角色扮演、逐段推断、错误回显或工具日志获得提示内容；模型也可能复述其语义。密钥、个人数据和真正需保密的规则不应进入提示。可公开的行为规范可以写入，敏感检测逻辑放在服务端。</p><p>提示泄露与指令违反是不同指标：模型不复述原文仍可能受低层恶意指令控制；反之公开规范被复述未必造成安全损失。先定义资产再测试。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>输出结构与拒绝路径必须可被消费者验证<span class=\"dd-badge eng\">接口</span></h2><p class=\"dd-lead\">模型说“需要批准”，下游为何不能只读这句话？</p><p>输出契约接收模型建议，输出版本化状态、字段和拒绝原因供消费者解析。消费者依次做类型、枚举、跨字段、身份和业务状态校验；自由文本解释不触发副作用。结构合法只表示格式通过，不证明订单所有权、金额或权限语义正确。</p><p>让模型产生版本化schema和明确状态，如 <code>propose_refund</code>、<code>needs_approval</code>、<code>insufficient_data</code>；消费者做类型、枚举、跨字段和业务校验。自由文本解释不能触发副作用，拒绝或缺信息也是一等状态。</p><p>结构化输出保证格式不保证语义；订单是否属于用户、金额是否允许仍由权威系统查询。提示和schema版本要一起回归，防消费者与模型契约漂移。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">10</span>会话、摘要和记忆会让旧提示假设漂移<span class=\"dd-badge eng\">长时状态</span></h2><p class=\"dd-lead\">系统提示未改，为什么长对话后行为仍可能变化？</p><p>长时状态装配输入系统不变量、历史、摘要、工具观察和带作用域记忆，输出本轮模型可见上下文。每轮重申必要边界并携带来源与可纠正状态，任务切换时清除局部记忆。初始规则只出现一次不能保证摘要后仍存在，也不能阻止旧目标跨任务残留。</p><p>历史消息、压缩摘要、工具观察和记忆不断改变条件上下文；旧用户目标可能被摘要成高置信事实，或跨任务残留。每轮重申必要的不变量，按任务/用户作用域读取记忆，并把来源与可纠正状态传给模型。</p><p>压缩后运行冲突和安全哨兵测试；任务切换时清除局部状态。不能依赖“最初说过一次”来保护长时Agent。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">11</span>版本化提示像代码，但回滚证据比文本diff更重要<span class=\"dd-badge eng\">发布</span></h2><p class=\"dd-lead\">只改一句措辞，为什么也可能改变完全无关的任务？</p><p>提示发布输入提示、模板、模型、采样、工具 schema 和评测集版本，输出带回归证据的候选版本与回滚包。文本变化会重新分配生成概率，须灰度比较任务成功、冲突、误拒、成本和人工修正。文本 diff 只说明改了什么，不能证明行为没有旁路回归。</p><p>提示变化会改变注意力和生成分布，影响不同语言、长上下文、工具选择和拒绝。保存提示、模板、模型、采样、工具schema和评测集版本；灰度比较任务成功、契约遵循、冲突解决、误拒、token成本和人工修正。</p><p>文本diff说明改了什么，不说明行为怎样变。发布需要冻结回归集、隐藏攻击集和生产影子样本；异常时能同时回滚提示与关联schema。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">12</span>契约测试覆盖正常、冲突、恶意和故障四象限<span class=\"dd-badge eng\">验证</span></h2><p class=\"dd-lead\">提示测试为什么不能只保存几个理想对话？</p><p>契约测试输入正常、冲突、恶意和故障四类样本，输出结构、决策、副作用与用户可见事实的断言结果。按语言、长度、版本和风险切片统计，并保留失败样例与置信区间；逐字措辞不必一致，但高风险动作和事实边界必须确定性通过。</p><p>正常集验证主任务；冲突集让用户、历史和工具内容与高层约束相反；恶意集覆盖注入、提取、编码与多轮；故障集覆盖缺字段、超时、拒绝和工具不一致。断言结构、决策、工具副作用和用户可见事实，而非逐字匹配措辞。</p><p>按语言、长度、模型版本和风险切片，报告置信区间与失败样例。模型评审可辅助扩展，但高风险判定使用确定性检查或人工复核。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">13</span>常见误区与概念依赖<span class=\"dd-badge intuition\">误区与学习路线</span></h2><p class=\"dd-lead\">系统提示是概率契约层，不是权限、秘密或业务真相。</p><div class=\"dd-note warn\"><b>初学者最易混淆：</b>“优先级更高”描述模型应遵循什么，不证明它每次都会遵循；安全设计必须假设遵循会失败。</div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>system消息不可覆盖</td><td>训练提高遵循倾向，不是形式保证</td></tr><tr><td>提示内规则能保密</td><td>默认可被复述或推断</td></tr><tr><td>提示可授权工具</td><td>权限由执行器和主体身份决定</td></tr><tr><td>越长越可靠</td><td>冲突与上下文竞争会增加</td></tr></tbody></table></div><p><b>学习路线：</b>先学上下文、结构化输出和工具调用，再学提示注入、指令层级、策略引擎与契约评测。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">14</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>把业务需求拆成稳定契约与动态数据</li><li>给每类上下文标记角色、来源和可信度</li><li>用最小提示声明目标、冲突和失败路径</li><li>让模型只提出结构化意图</li><li>由确定性策略核验身份、权限和业务状态</li><li>把工具事实回传而不伪造成功</li><li>用四象限契约集评测并灰度发布</li><li>监控长时状态漂移并版本化回滚</li></ol>\n      <div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>验证层</th><th>在“系统提示：在概率模型里声明行为契约，而不是建立安全边界”中固定什么</th><th>观察什么证据</th></tr></thead><tbody>\n      <tr><td>输入</td><td>同一批样本、前处理与权限边界</td><td>输入哈希、切片标签和拒绝原因</td></tr>\n      <tr><td>机制</td><td>仅改变一个核心变量，其余配置锁定</td><td>关键中间状态及首次偏离预期的位置</td></tr>\n      <tr><td>输出</td><td>同一验收规则与资源预算</td><td>质量、成本、延迟和失败率的分层差异</td></tr>\n      <tr><td>反证</td><td>保留不启用目标机制的对照组</td><td>收益是否跨样本与随机种子稳定复现</td></tr>\n      </tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">15</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>系统提示为何不是安全边界？</li><li>时间更晚的用户消息能否覆盖系统规则？</li><li>为什么提示里不能放密钥？</li><li>结构化输出还需什么校验？</li><li>提示发布为何需要行为回归？</li><li>假设“系统提示：在概率模型里声明行为契约，而不是建立安全边界”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“系统提示：在概率模型里声明行为契约，而不是建立安全边界”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>它仍是模型条件上下文，遵循是概率行为；权限和副作用必须由执行层保证。</li><li>按设计不应；跨层冲突由信任优先级而非时间顺序决定，但仍需测试。</li><li>提示可能被直接复述、间接推断或通过日志泄露。</li><li>类型、跨字段、授权和权威业务状态校验。</li><li>小文本变化也会改变多任务、语言、工具选择和拒绝分布。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2404.13208\" target=\"_blank\" rel=\"noopener\">The Instruction Hierarchy</a>：训练模型优先遵循特权指令</li><li><a href=\"https://arxiv.org/abs/2502.08745\" target=\"_blank\" rel=\"noopener\">IHEval</a>：对齐与冲突指令层级评测</li><li><a href=\"https://arxiv.org/abs/2302.12173\" target=\"_blank\" rel=\"noopener\">Indirect Prompt Injection</a>：外部数据中的间接指令攻击</li><li><a href=\"https://arxiv.org/abs/2402.06363\" target=\"_blank\" rel=\"noopener\">StruQ</a>：结构化查询与提示注入防御研究</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
